import{_ as e,o as r,c as a,a2 as t}from"./chunks/framework.BVc2lkLk.js";const u=JSON.parse('{"title":"绑定自定义域名","description":"QQ 开放平台访问不到 workers.dev，机器人的回调地址要用托管在 Cloudflare 上的自定义域名，这里说明怎么准备和绑定。","frontmatter":{"description":"QQ 开放平台访问不到 workers.dev，机器人的回调地址要用托管在 Cloudflare 上的自定义域名，这里说明怎么准备和绑定。"},"headers":[],"relativePath":"deploy-domain.md","filePath":"deploy-domain.md","lastUpdated":1790607621000}'),l={name:"deploy-domain.md"};function d(s,o,n,i,c,p){return r(),a("div",null,[...o[0]||(o[0]=[t('<h1 id="绑定自定义域名" tabindex="-1">绑定自定义域名 <a class="header-anchor" href="#绑定自定义域名" aria-label="Permalink to &quot;绑定自定义域名&quot;">​</a></h1><p>QQ 开放平台访问不到 <code>*.workers.dev</code>（实测回调地址校验不通过），所以回调必须走你自己的域名。引导不会替你选域名，也不会替你绑：域名由你在 Cloudflare 后台自己加，之后重跑引导或自部署构建都不会改动它。</p><h2 id="准备域名" tabindex="-1">准备域名 <a class="header-anchor" href="#准备域名" aria-label="Permalink to &quot;准备域名&quot;">​</a></h2><p>域名必须托管在<strong>部署机器人的同一个 Cloudflare 账户</strong>下。</p><ul><li><strong>已经在 Cloudflare 上</strong>：直接看下一节。</li><li><strong>还没有域名</strong>：在任意注册商买一个（Cloudflare 自己的注册商也行，按成本价卖）；不想花钱的话，找个免费的二级域名也行，只要能把 NS 改成 Cloudflare 的。</li><li><strong>域名在别的服务商那里解析</strong>：在 Cloudflare 后台点 <strong>Add a domain</strong>（添加域名），按提示到注册商那里把域名的 NS 服务器改成 Cloudflare 给的两个。等域名状态变成 <strong>Active</strong> 再继续，通常几分钟到几小时。</li></ul><p>建议用一个子域名（如 <code>bot.example.com</code>）专门给机器人，别占用主站。</p><h2 id="绑定到-worker" tabindex="-1">绑定到 Worker <a class="header-anchor" href="#绑定到-worker" aria-label="Permalink to &quot;绑定到 Worker&quot;">​</a></h2><ol><li>打开 Cloudflare 后台，进入 <strong>Workers &amp; Pages</strong>（计算），点你的 Worker（默认叫 <code>qqbot</code>）。</li><li>切到 <strong>Settings</strong> 标签页，找到 <strong>Domains &amp; Routes</strong>，点 <strong>Add</strong>，选 <strong>Custom domain</strong>。</li><li>输入域名，如 <code>bot.example.com</code>，点 <strong>Add domain</strong>。</li></ol><p>Cloudflare 会自动创建 DNS 记录并签发 HTTPS 证书，一般几分钟就好。要是提示这个名字已经有 DNS 记录，先到域名的 DNS 页面删掉那条旧记录再试。</p><h2 id="确认" tabindex="-1">确认 <a class="header-anchor" href="#确认" aria-label="Permalink to &quot;确认&quot;">​</a></h2><p>用浏览器打开 <code>https://bot.example.com/</code>，能看到面板登录页就说明绑好了。用 <code>ADMIN_TOKEN</code> 登录，概览页的「回调地址」卡片会显示 <code>https://bot.example.com/webhook</code>，下一步把它填到 QQ 开放平台。</p><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li><strong>不要关掉 workers.dev</strong>。Worker 的 Domains &amp; Routes 里那条 <code>*.workers.dev</code> 路由要留着：构建机装插件、更新插件时从这个地址拉插件清单，关掉以后构建会失败。</li><li>QQ 开放平台只允许回调地址用 80 / 443 / 8080 / 8443 端口。Custom Domain 走的是 443，不用额外设置。</li></ul><p>下一步：<a href="./deploy-qq">配置 QQ 开放平台</a>。</p>',14)])])}const h=e(l,[["render",d]]);export{u as __pageData,h as default};
